    {P : ℕ → D → ℝ} {α κ : ℝ} {d : GraphDirections D} {a : WaveCoefficients D}
    (h : InputBounds s P α κ d a) {ψ : ℕ → D → ℝ} (hψ : UnweightedClass s 0 ψ)
    {f source : ℕ → D → ComplexVector} {β : ℝ}
    (hf : ∀ i, WaveClass s P β (fun n x => f n x i)) (n : ℕ) {x : D}
